"""V-CFO-3 (E1): the ANTS Fig. 2 sweep regenerated by two OS processes over native ZMQ
(DESIGN.md sections 10.10, 11 E-E1; RQ-35).

Setup: the V-CFO-1 port of the v1 BPSK pair (200-symbol header of 1+1j, 38 BPSK symbols at
+-0.1(1+j), 10 samples per symbol, 2389 samples at 5880 S/s) through the V-CFO-1 engine
(static SIM link with a RIS, noise off, lockstep), with the receiver's LO offset swept from
-1400 to +1400 Hz in 100 Hz steps. Each sweep point is one served emulator; a **TX
generator process** sends the waveform in 2 ms client epochs (12 samples) and an **RX sink
process** receives 2389 samples, both through ``sremu.Device.connect`` over the control
socket and the native framed data plane.

Acceptance (section 10.10): 2389 samples delivered exactly per point; the unwrapped-phase
LS estimator on the header gives a sweep with slope 1 +- 0.002 and |intercept| < 2 Hz
(noise off); every received waveform is bitwise equal to V-CFO-1's in-process output (the
V-CFO-1 test's own ``_receive``), so the V-CFO-1 exactness |f_hat - f| <= 1e-6 Hz carries
over and is checked as well.
"""

from __future__ import annotations

from fractions import Fraction
from pathlib import Path

import numpy as np
import pytest

from sremu.engine.streams import bpsk_v1_waveform
from tests.io._wp8_support import bits, client_cmd, run_clients, serve, vcfo_engine
from tests.runtime.test_vcfo_engine import FC, SWEEP, _est_lag1, _est_ls, _receive

pytestmark = pytest.mark.integration

FS = 5880.0


def test_vcfo3_two_process_sweep_slope_one_bitwise_vcfo1(tmp_path: Path) -> None:
    x = bpsk_v1_waveform()
    np.save(tmp_path / "x.npy", x)
    servers = [serve(vcfo_engine(float(f)), start_paused=True) for f in SWEEP]
    try:
        eps = ",".join(str(s.endpoints["control"]) for s in servers)
        outs = run_clients(
            [
                client_cmd(
                    "rx",
                    "--sessions",
                    eps,
                    "--stream",
                    "rx.rx0",
                    "--fc",
                    repr(FC),
                    "--rate",
                    "5880",
                    "--n",
                    str(x.size),
                    "--out",
                    str(tmp_path),
                    "--chunk",
                    "12",
                ),
                client_cmd(
                    "tx",
                    "--sessions",
                    eps,
                    "--stream",
                    "tx.tx0",
                    "--fc",
                    repr(FC),
                    "--rate",
                    "5880",
                    "--x",
                    str(tmp_path / "x.npy"),
                    "--chunks",
                    "12",
                ),
            ],
            timeout_s=600,
        )
        for s in servers:
            assert s.counters["bad_packets"] == 0 and s.counters["seq_errors"] == 0
            assert s.engine_error is None
    finally:
        for s in servers:
            s.stop()
    assert "rx received 2389" in outs[0]
    est = []
    for j, f in enumerate(SWEEP):
        y = np.load(tmp_path / f"{j}_rx.rx0.npy")
        assert y.shape == (2389,) and y.dtype == np.complex64
        assert np.array_equal(bits(y), bits(_receive(float(f), Fraction(2, 1000)))), f
        f_ls = _est_ls(y, FS)
        assert abs(f_ls - f) <= 1e-6, (f, f_ls)
        assert abs(_est_lag1(y, FS) - f) <= 1e-6, f
        est.append(f_ls)
    slope, intercept = np.polyfit(SWEEP, np.asarray(est), 1)
    assert abs(slope - 1.0) <= 0.002
    assert abs(intercept) < 2.0
